import{_ as t,o as i,c as u,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-11.png",a="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-12.png",h="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-13.png",g="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-14.png",k=JSON.parse('{"title":"Ergebnisse der Versetzungs- und Abschlussberechnung prüfen","description":"","frontmatter":{"title":"Ergebnisse der Versetzungs- und Abschlussberechnung prüfen","source_pageid":543,"source_revision":6090},"headers":[],"relativePath":"zeugnisse/vorbereitung/ergebnis-versetzungs-abschluss-berechnung-aktuelles-halbjahr-aktueller-abschnitt.md","filePath":"zeugnisse/vorbereitung/ergebnis-versetzungs-abschluss-berechnung-aktuelles-halbjahr-aktueller-abschnitt.md"}'),c={name:"zeugnisse/vorbereitung/ergebnis-versetzungs-abschluss-berechnung-aktuelles-halbjahr-aktueller-abschnitt.md"};function d(b,r,o,p,m,f){return i(),u("div",null,[...r[0]||(r[0]=[s('<h1 id="ergebnisse-der-versetzungs-und-abschlussberechnung-prufen" tabindex="-1">Ergebnisse der Versetzungs- und Abschlussberechnung prüfen <a class="header-anchor" href="#ergebnisse-der-versetzungs-und-abschlussberechnung-prufen" aria-label="Permalink to &quot;Ergebnisse der Versetzungs- und Abschlussberechnung prüfen&quot;">​</a></h1><p>Lesen Sie die gespeicherten Ergebnisse einer durchgeführten Berechnung mit Fehlerhinweisen und möglichen Ausgleichen. Die endgültige Entscheidung bleibt bei der Schule und den zuständigen Konferenzen.</p><p><a href="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-11.png"><img src="'+l+'" alt="Manuelle Abschlussberechnung." loading="lazy"></a></p><p><em>Manuelle Abschlussberechnung.</em></p><p>Im Reiter <em>&quot;Ergebnis Versetzungs-/Abschlussberechnung&quot;</em> werden die Details einer durchgeführten Versetzungs- und/oder Abschlussberechnung festgehalten.</p><p>In diesem Ergebnis werden Fehler oder Anmerkungen zu möglichen Ausgleichen aufgeführt.</p><p>Eine Berechnung lässt sich manuell über den Schalter <em>Schüler</em> ➜ <em>Akt. Halbjahr</em> ➜ <em>Leistungsdaten</em> ➜ <strong>Versetzungs-/Abschluss-Berechnung</strong> für die individuell ausgewählte Person anstoßen.</p><p><a href="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-12.png"><img src="'+a+'" alt="Abschlussberechnung per Gruppenprozess." loading="lazy"></a></p><p><em>Abschlussberechnung per Gruppenprozess.</em></p><p>Alternativ starten Sie für eine Schülergruppe den Gruppenprozess <strong>Versetzungs-/Abschluss-Berechnung</strong>. Danach können Sie die Ergebnisse für jede Person im Reiter <strong>Ergebnis Versetzungs-/Abschlussberechnung</strong> prüfen.</p>',10),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die Verantwortung für die Korrektheit von Versetzungen und Abschlüssen trägt die Schule über Prüfungen durch die betreuende Lehrkraft und Beschlüsse der Zeugniskonferenzen. Die automatische Prüfung über Schulverwaltungssoftware ist als Hilfestellung ohne Gewähr zu verstehen.")],-1),s('<p><a href="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-13.png"><img src="'+h+'" alt="Reiter für Abitur und FHR werden eingeblendet, wenn im Container die entsprechenden Jahrgänge exklusiv ausgewählt wurden.." loading="lazy"></a></p><p><em>Reiter für Abitur und FHR werden eingeblendet, wenn im Container die entsprechenden Jahrgänge exklusiv ausgewählt wurden..</em></p><p>Um Berechnungen für das Abitur beziehungsweise die FHR durchzuführen, werden in dafür relevanten Jahrgängen die Reiter <em>FHR</em> und <em>Abitur</em> eingeblendet.</p><p><a href="/bilder/vorbereitung/schueler-akt-halbj-leistungsdaten-14.png"><img src="'+g+'" alt="Gruppenprozesse zum Abitur." loading="lazy"></a></p><p><em>Gruppenprozesse zum Abitur.</em></p><p>Unter <em>Gruppenprozesse</em> werden dann ebenfalls Felder für Abitur und FHR eingeblendet.</p>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die Ergebnisse der Berechnungen werden für jeden Lernabschnitt gespeichert. Entsprechend ist es auch möglich, nachträglich für Lernabschnitte diese Berechnungen durchzuführen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Ergebnis_Versetzungs-/Abschluss-Berechnung_(Aktuelles_Halbjahr_/_Aktueller_Abschnitt",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6090.")],-1)])])}const v=t(c,[["render",d]]);export{k as __pageData,v as default};
